query:
UPDATE blog_posts 
SET imageUrl = REGEXP_SUBSTR(content, 'https?://[^)]+\\.(?:jpeg|jpg|png|webp|gif)')
WHERE imageUrl IS NULL 
  AND content REGEXP '!\\[.*?\\]\\(https?://';
SELECT id, title, slug, imageUrl FROM blog_posts ORDER BY id DESC LIMIT 20;

